function Icon({ name, className = "h-5 w-5", strokeWidth = 1.5 }) {
  const base = { className, viewBox: "0 0 24 24", fill: "none", stroke: "currentColor", strokeWidth, strokeLinecap: "round", strokeLinejoin: "round", "aria-hidden": true };
  if (name === "arrow") return <svg {...base}><path d="M4 12h15m-6-6 6 6-6 6" /></svg>;
  if (name === "right") return <svg {...base}><path d="M4 12h16m-6-6 6 6-6 6" /></svg>;
  if (name === "left") return <svg {...base}><path d="M20 12H4m6 6-6-6 6-6" /></svg>;
  if (name === "down") return <svg {...base}><path d="M12 3v18m-6-6 6 6 6-6" /></svg>;
  if (name === "close") return <svg {...base}><path d="M5 5l14 14M19 5L5 19" /></svg>;
  if (name === "gift") return <svg {...base}><rect x="3" y="10" width="18" height="11" rx="1.5"/><path d="M12 10v11M3 14h18M3 10V7h18v3M12 7c-3-5-8-5-8-1 0 2 3 2 8 1Zm0 0c3-5 8-5 8-1 0 2-3 2-8 1Z" /></svg>;
  if (name === "diamond") return <svg {...base}><path d="M6.5 4h11l4 6-9.5 10L2.5 10l4-6Zm-4 6h19M9 4l-2 6 5 10 5-10-2-6" /></svg>;
  if (name === "heart") return <svg {...base}><path d="M20.8 9.1c0 4.8-8.8 10-8.8 10s-8.8-5.2-8.8-10a4.7 4.7 0 0 1 8.8-2.2 4.7 4.7 0 0 1 8.8 2.2Z" /></svg>;
  if (name === "feather") return <svg {...base}><path d="M20 4C7 4 4 9 4 19c8 0 14-4 16-15ZM4 19l11-10M4 19v2" /></svg>;
  if (name === "card") return <svg {...base}><rect x="4" y="4" width="16" height="16" rx="2"/><path d="M8 9h8M8 13h6" /></svg>;
  if (name === "spark") return <svg {...base}><path d="m12 2 2.25 7.75L22 12l-7.75 2.25L12 22l-2.25-7.75L2 12l7.75-2.25L12 2Z" /></svg>;
  if (name === "check") return <svg {...base}><path d="m4 12 5 5L20 6" /></svg>;
  return null;
}

function scrollToSection(id) {
  if (typeof document === "undefined") return;
  const reduced = window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches;
  document.getElementById(id)?.scrollIntoView({ behavior: reduced ? "auto" : "smooth", block: "start" });
}

function ComingSoonDialog({ edition, onClose }) {
  const modalRef = useRef(null);
  const closeRef = useRef(null);
  const isEdition = Boolean(edition);

  useEffect(() => {
    const previousOverflow = document.body.style.overflow;
    const previousFocus = document.activeElement;
    document.body.style.overflow = "hidden";
    closeRef.current?.focus();
    const onKey = (event) => {
      if (event.key === "Escape") { onClose(); return; }
      if (event.key !== "Tab" || !modalRef.current) return;
      const controls = Array.from(modalRef.current.querySelectorAll('button:not([disabled]),a[href]'));
      if (!controls.length) return;
      const first = controls[0], last = controls[controls.length - 1];
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
      if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
    };
    document.addEventListener("keydown", onKey);
    return () => {
      document.body.style.overflow = previousOverflow;
      document.removeEventListener("keydown", onKey);
      previousFocus?.focus?.();
    };
  }, [onClose]);

  return (
    <div
      className="h1-popup-backdrop fixed inset-0 z-[1000] flex items-center justify-center overflow-y-auto bg-[#120c08]/55 p-4 sm:p-6"
      onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}
    >
      <section
        ref={modalRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby="h1-coming-title"
        aria-describedby="h1-coming-description"
        className="h1-popup-enter relative my-auto w-full max-w-[465px] overflow-hidden rounded-[20px] border border-[#e0d3bf] bg-[#fcf8f1] px-6 pb-9 pt-10 text-center text-[#22180f] shadow-[0_30px_100px_rgba(0,0,0,.35)] sm:px-12 sm:pb-11 sm:pt-13"
      >
        <button
          ref={closeRef}
          type="button"
          aria-label="Close Coming Soon popup"
          onClick={onClose}
          className="h1-popup-close absolute right-4 top-4 flex h-9 w-9 items-center justify-center rounded-full border border-[#b38b58] bg-white/80 text-[#49311b] transition hover:bg-[#efe2cc]"
        ><Icon name="close" className="h-4 w-4"/></button>
        <div className="mx-auto mb-5 flex h-[55px] w-[55px] items-center justify-center text-[#be8a37]"><Icon name="gift" className="h-[46px] w-[46px]" strokeWidth={1.2} /></div>
        <p className="h1-overline !text-[#996027]">HAMPER ONE</p>
        <h2 id="h1-coming-title" className="h1-serif mt-3 text-[clamp(3.25rem,9vw,4.75rem)] font-bold leading-[.94] tracking-[-.055em]">
          {isEdition ? "Coming Soon" : "Coming Soon"}
        </h2>
        <p id="h1-coming-description" className="mx-auto mt-5 max-w-[325px] text-[14px] leading-[1.75] text-[#6b5948] sm:text-[15px]">
          {isEdition
            ? `${edition.name.replace(/^THE /, "The ")} is being thoughtfully curated. The collection and personalisation experience will be available soon.`
            : "We're creating something truly special. HAMPER ONE will soon bring you premium ready-made hampers with considered personalisation options."}
        </p>
        <button type="button" className="h1-gold-button mx-auto mt-7 inline-flex min-h-12 items-center justify-center gap-4 rounded-full px-7 text-[14px] font-bold" onClick={onClose}>
          Explore the Preview <Icon name="arrow" className="h-4 w-4" />
        </button>
        <span className="mx-auto mt-6 block h-px w-14 bg-[#d2b487]" aria-hidden="true" />
        <p className="mt-3 text-[10px] font-semibold uppercase tracking-[.19em] text-[#ad9981]">Exclusively by HAMPORIUM</p>
      </section>
    </div>
  );
}

